p='/output/data/gadm41_GBR_1.json'; x=json.load(open(p))
for f in x['features']:
 g=f['geometry']
 pts=[]
 def walk(z):
  if isinstance(z[0],(float,int)): pts.append(z)
  else:
   for y in z: walk(y)
 walk(g['coordinates'])
 print(f['properties']['GID_1'],f['properties']['NAME_1'],len(pts), min(a[0] for a in pts),max(a[0] for a in pts),min(a[1] for a in pts),max(a[1] for a in pts))
